solution.solution.cpp:
#include <sstream>
#include <string>
#include <vector>

struct Point { int x, y; };
struct LevelData
{
    int width{ 0 }, height{ 0 };
    std::vector<std::string> grid;
    Point player{ -1, -1 };
    std::vector<Point> enemies, coins;
};

bool loadLevel(const std::string& text, LevelData& out, std::string& error)
{
    std::istringstream in{ text };
    std::vector<std::string> lines;
    for (std::string l; std::getline(in, l);) { if (!l.empty() && l.back() == '\r') l.pop_back(); lines.push_back(l); }

    LevelData level;
    bool haveSize{ false };
    std::size_t i{ 0 };
    for (; i < lines.size(); ++i)
    {
        const std::string& l{ lines[i] };
        if (l.empty() || l.rfind("# ", 0) == 0) continue;
        if (l.rfind("size", 0) == 0)
        {
            std::istringstream s{ l.substr(4) };
            std::string extra;
            if (!(s >> level.width >> level.height) || (s >> extra) || level.width < 1 || level.height < 1 || level.width > 500 || level.height > 500)
            { error = "bad size"; return false; }
            haveSize = true;
            continue;
        }
        if (l.rfind("legend", 0) == 0) continue;
        break;
    }
    if (!haveSize) { error = "missing size"; return false; }
    if (lines.size() - i != static_cast<std::size_t>(level.height)) { error = "wrong row count"; return false; }

    int players{ 0 };
    for (int y{ 0 }; y < level.height; ++y)
    {
        std::string row{ lines[i + static_cast<std::size_t>(y)] };
        if (static_cast<int>(row.size()) != level.width) { error = "row " + std::to_string(y + 1) + " has the wrong length"; return false; }
        for (int x{ 0 }; x < level.width; ++x)
        {
            char& c{ row[static_cast<std::size_t>(x)] };
            switch (c)
            {
            case '#': case '=': case '.': break;
            case 'P': ++players; level.player = { x, y }; c = '.'; break;
            case 'E': level.enemies.push_back({ x, y }); c = '.'; break;
            case 'C': level.coins.push_back({ x, y }); c = '.'; break;
            default: error = std::string("unknown tile '") + c + "' in row " + std::to_string(y + 1); return false;
            }
        }
        level.grid.push_back(row);
    }
    if (players == 0) { error = "no player start"; return false; }
    if (players > 1) { error = "more than one player start"; return false; }
    out = std::move(level);
    return true;
}

int wallMask(const LevelData& level, int x, int y)
{
    auto wall = [&](int cx, int cy) {
        if (cx < 0 || cy < 0 || cx >= level.width || cy >= level.height) return false;
        const char c{ level.grid[static_cast<std::size_t>(cy)][static_cast<std::size_t>(cx)] };
        return c == '#' || c == '=';
    };
    if (!wall(x, y)) return -1;
    return (wall(x, y - 1) ? 1 : 0) | (wall(x + 1, y) ? 2 : 0) | (wall(x, y + 1) ? 4 : 0) | (wall(x - 1, y) ? 8 : 0);
}

unitTests:
const std::string good =
    "# level 1
size 6 4
legend # stone, = grass

"
    "..C.E.
.P..==
###..#
######
";
TEST("a good level") {
    LevelData l; std::string err; CHECK(loadLevel(good, l, err));
    CHECK_EQ(l.width, 6); CHECK_EQ(l.height, 4); CHECK_EQ(l.player.x, 1); CHECK_EQ(l.player.y, 1);
    CHECK_EQ(l.coins.size(), std::size_t{ 1 }); CHECK_EQ(l.coins[0].x, 2); CHECK_EQ(l.enemies[0].x, 4);
    CHECK_EQ(l.grid[0], std::string("......")); CHECK_EQ(l.grid[1], std::string("....=="));
}
TEST("errors") {
    LevelData l; std::string err;
    CHECK(!loadLevel("P
", l, err)); CHECK_EQ(err, std::string("missing size"));
    CHECK(!loadLevel("size 0 3
", l, err)); CHECK_EQ(err, std::string("bad size"));
    CHECK(!loadLevel("size 2 2
P.
", l, err)); CHECK_EQ(err, std::string("wrong row count"));
    CHECK(!loadLevel("size 2 2
P.
...
", l, err)); CHECK_EQ(err, std::string("row 2 has the wrong length"));
    CHECK(!loadLevel("size 2 2
P.
.?
", l, err)); CHECK_EQ(err, std::string("unknown tile '?' in row 2"));
    CHECK(!loadLevel("size 2 1
..
", l, err)); CHECK_EQ(err, std::string("no player start"));
    CHECK(!loadLevel("size 2 1
PP
", l, err)); CHECK_EQ(err, std::string("more than one player start"));
}
TEST("a comment-like row inside the grid is a row") { LevelData l; std::string err; CHECK(!loadLevel("size 3 2
P..
# a
", l, err)); CHECK_EQ(err, std::string("unknown tile ' ' in row 2")); }
TEST("auto-tiling") {
    LevelData l; std::string err; loadLevel(good, l, err);
    CHECK_EQ(wallMask(l, 0, 0), -1); CHECK_EQ(wallMask(l, 0, 2), 6); CHECK_EQ(wallMask(l, 1, 2), 14); CHECK_EQ(wallMask(l, 2, 3), 9 | 2);
    CHECK_EQ(wallMask(l, 5, 2), 5); CHECK_EQ(wallMask(l, 4, 1), 2); CHECK_EQ(wallMask(l, 5, 1), 12);
}

